CREATE TABLE onboarding_application (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entity_type VARCHAR(32), legal_name VARCHAR(255), pan VARCHAR(10), gstin VARCHAR(15), address_line1 VARCHAR(255), city VARCHAR(100), pincode VARCHAR(6), industry_code VARCHAR(100), expected_monthly_turnover DECIMAL(19,2), expected_monthly_cash_deposit DECIMAL(19,2), owner VARCHAR(100), status VARCHAR(32), risk_tier VARCHAR(16), risk_score INTEGER, submitted_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE related_party (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, application_id BIGINT NOT NULL, name VARCHAR(255), pan VARCHAR(10), mobile VARCHAR(10), role VARCHAR(32), ownership_percent DECIMAL(8,2), signatory BOOLEAN, pep BOOLEAN, nationality VARCHAR(10));
CREATE TABLE risk_factor (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, application_id BIGINT NOT NULL, code VARCHAR(100), points INTEGER, reason VARCHAR(1000));
CREATE TABLE onboarding_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, application_id BIGINT NOT NULL, actor VARCHAR(100), action VARCHAR(32), from_status VARCHAR(32), to_status VARCHAR(32), note VARCHAR(2000), details VARCHAR(2000), at TIMESTAMP WITH TIME ZONE);
CREATE INDEX idx_application_status_tier_submitted ON onboarding_application(status, risk_tier, submitted_at);
